'use strict';
// Read-only public data channel. No credentials, arbitrary URLs or executable content.
const publicDataBase='/api/forecasts/';
const publicDataFiles=['cfs-weekly-raw-60days.json','cfs-weekly-anomalies.json','enso-observations.json','ensemble-percentiles.json','verification.json','cfs-global-60days.json','aifs-global-snapshots.json'];
const publicDataCache='enso-atlas-object-storage-v1';let publicDataBusy=false;
const {requireData,goodDate,numericArray,validatePublicProducts}=AtlasForecastSchema;
async function verifyPublicBundle(bundle){const m=bundle.manifest;requireData(m?.schemaVersion===1&&m.storageVersion===1&&/^[a-f0-9]{64}$/.test(m.releaseID)&&goodDate(m.generatedAt),'Invalid manifest');requireData(Object.keys(m.files||{}).sort().join('|')===publicDataFiles.slice().sort().join('|'),'Unexpected manifest files');const p={};for(const name of publicDataFiles){const text=bundle.texts[name],meta=m.files[name];requireData(typeof text==='string'&&meta.bytes>0&&meta.bytes<5000000&&/^[a-f0-9]{64}$/.test(meta.sha256),'Invalid file metadata');const bytes=new TextEncoder().encode(text);requireData(bytes.length===meta.bytes,'Byte count mismatch');const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');requireData(hash===meta.sha256,'Hash mismatch');p[name]=JSON.parse(text)}validatePublicProducts(p);if(p['aifs-global-snapshots.json'].fineFirstWeek)await AtlasAifsFine.prepare(p['aifs-global-snapshots.json']);return p}
function applyPublicData(p,manifest,checkedAt){const locations=cfs?.sampledLocations;const oldWeek=longWeek;cfs=p[publicDataFiles[0]];if(locations)cfs.sampledLocations=locations;anomalies=p[publicDataFiles[1]];ensoLatest=p[publicDataFiles[2]].observations.at(-1);ensemble=p[publicDataFiles[3]];longWeek=oldWeek;setupWeeks();feedDescription='Hash-verified NOAA storage data · generated '+manifest.generatedAt.slice(0,16).replace('T',' ')+' UTC · checked '+checkedAt.slice(0,16).replace('T',' ')+' UTC';$('feedStatus').textContent=feedDescription;renderEnso();if(longMode)renderLong();if(typeof globalAssets!=='undefined'){globalAssets.cfs=p['cfs-global-60days.json'];globalAssets.aifs=p['aifs-global-snapshots.json'];if(globalMode)renderGlobal()}if(typeof verificationReport!=='undefined'){verificationReport=p['verification.json'];renderVerification();if(typeof loadVerificationArchive==='function')loadVerificationArchive(verificationReport)}}
// Worldwide bundles exceed common localStorage quotas. IndexedDB keeps one verified
// last-good bundle without blocking the UI; constrained browsers use the old fallback.
async function forecastCache(mode,bundle){
 if(typeof indexedDB==='undefined'){if(mode==='get'){try{return JSON.parse(localStorage.getItem(publicDataCache))}catch{return null}}try{localStorage.setItem(publicDataCache,JSON.stringify(bundle))}catch{}return null}
 return new Promise(resolve=>{let settled=false,db=null;const finish=value=>{if(settled)return;settled=true;clearTimeout(timeout);try{db?.close()}catch{}resolve(value)};const timeout=setTimeout(()=>finish(null),3000);let open;try{open=indexedDB.open(publicDataCache,1)}catch{finish(null);return}open.onupgradeneeded=()=>{if(!open.result.objectStoreNames.contains('bundles'))open.result.createObjectStore('bundles')};open.onerror=()=>finish(null);open.onblocked=()=>finish(null);open.onsuccess=()=>{db=open.result;if(settled){db.close();return}try{const transaction=db.transaction('bundles',mode==='get'?'readonly':'readwrite'),request=mode==='get'?transaction.objectStore('bundles').get('latest'):transaction.objectStore('bundles').put(bundle,'latest');let result=null;request.onsuccess=()=>{result=request.result};transaction.oncomplete=()=>finish(mode==='get'?result:null);transaction.onerror=()=>finish(null);transaction.onabort=()=>finish(null)}catch{finish(null)}}});
}
function bundleNotOlderThanLoaded(p){const checks=[[p['cfs-weekly-raw-60days.json']?.run,cfs?.run],[p['ensemble-percentiles.json']?.run,ensemble?.run],[p['cfs-weekly-anomalies.json']?.initialDate,anomalies?.initialDate],[p['enso-observations.json']?.observations?.at(-1)?.date,ensoLatest?.date]];if(typeof globalAssets!=='undefined')checks.push([p['cfs-global-60days.json']?.run,globalAssets.cfs?.run],[p['aifs-global-snapshots.json']?.run,globalAssets.aifs?.run]);return checks.every(([incoming,current])=>!current||goodDate(incoming)&&Date.parse(incoming)>=Date.parse(current))}
async function refreshPublicData(force=false){if(publicDataBusy)return;publicDataBusy=true;try{await Promise.all([initialLoad,ensembleLoad,typeof globalLoad==='undefined'?Promise.resolve():globalLoad]);requireData(crypto?.subtle,'Secure hash validation unavailable');const cached=await forecastCache('get');if(cached){try{const age=Date.now()-Date.parse(cached.checkedAt);requireData(goodDate(cached.checkedAt)&&age>=0,'Invalid cached source-check time');const p=await verifyPublicBundle(cached);requireData(bundleNotOlderThanLoaded(p),'Cached source is older than current source');applyPublicData(p,cached.manifest,cached.checkedAt);if(!force&&age<3600000)return}catch{}}
 const bucket=Math.floor(Date.now()/3600000),r=await fetch(publicDataBase+'manifest?v='+bucket,{cache:'no-cache',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Manifest not available');const manifest=await r.json();requireData(manifest?.files,'Missing file list');const texts={};for(const name of publicDataFiles){requireData(manifest.files[name]?.sha256,'Missing file hash');const response=await fetch(publicDataBase+'objects/'+manifest.files[name].sha256+'/'+name,{signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error('Data unavailable');texts[name]=await response.text()}
 const bundle={manifest,texts,checkedAt:new Date().toISOString()},p=await verifyPublicBundle(bundle);requireData(bundleNotOlderThanLoaded(p),'Stored source is older than current source');applyPublicData(p,manifest,bundle.checkedAt);await forecastCache('put',bundle);
 }catch{const el=$('feedStatus');if(el)el.textContent='Forecast storage refresh unavailable or failed validation. Keeping the previous source data; check each product’s run date.'}finally{publicDataBusy=false;if(typeof syncExplorerState==='function')syncExplorerState()}}
refreshPublicData();setInterval(()=>{if(document.visibilityState==='visible'){refreshPublicData();if(typeof refresh==='function'&&typeof globalMode!=='undefined'&&!globalMode&&!longMode)refresh()}},3600000);
